function editCurrency() {
  const c=character(),before=Object.fromEntries(Object.keys(COINS).map(key=>[key,c[key]]));
  const calculate=(key,value)=>{try{return calculateMoney(before[key],value);}catch(error){throw new Error(`${coinName(key)}: ${error.message}`);}};
  setModal('A little treasure to your name.',`<p class="modal-intro" id="currency-help">Enter a total, <strong>+10</strong> to add, or <strong>−5</strong> to spend. You can also calculate <strong>25+10−5</strong>. Each coin type is counted separately.</p><div class="form-grid">${Object.entries(COINS).map(([key,unit])=>`<label class="form-field"><span class="coin-field-label">${coinStud(key)}${coinName(key)} pieces (${unit.toUpperCase()})</span><input name="${key}" type="text" value="${c[key]}" required maxlength="120" spellcheck="false" autocomplete="off" aria-describedby="currency-help ${key}-result" data-currency-input="${key}"><span class="coin-calculation" id="${key}-result" aria-live="polite">Balance: ${fmt(c[key])} ${unit.toUpperCase()}</span></label>`).join('')}</div>${actions('Update purse')}`,data=>{
    // Validate every denomination before changing any saved balance.
    const next=Object.fromEntries(Object.keys(COINS).map(key=>[key,calculate(key,data.get(key))]));
    const studs=Object.keys(COINS).map(denomination=>({denomination,amount:next[denomination]-before[denomination]})).filter(change=>change.amount);
    Object.assign(c,next);modal.close();commit('Coin purse updated.');
    if(studs.length){sound.play('item.coin');playEffect('money',{label:studs.map(({denomination,amount})=>`${amount>0?'+':'−'}${fmt(Math.abs(amount))} ${COINS[denomination].toUpperCase()}`).join(' · '),detail:'COIN PURSE UPDATED',target:'.coin-balances',sigil:false,studs});}
  });
  for(const input of modal.querySelectorAll('[data-currency-input]'))input.addEventListener('input',()=>{
    $('#form-error').hidden=true;
    const key=input.dataset.currencyInput,unit=COINS[key].toUpperCase(),result=modal.querySelector(`#${key}-result`);
    try {
      const total=calculate(key,input.value);input.removeAttribute('aria-invalid');
      result.classList.remove('coin-calculation-error');
      result.textContent=total===before[key]?`Balance: ${fmt(total)} ${unit}`:`${fmt(before[key])} ${unit} → ${fmt(total)} ${unit}`;
    } catch(error) {
      input.setAttribute('aria-invalid','true');result.classList.add('coin-calculation-error');result.textContent=error.message;
    }
  });
}

